INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Datenübertragungsrate dasselbe wie die Bandbreite?', 2, '[{"text": "Nein", "correct": true, "because": "Rate ist tatsächliche Geschwindigkeit, Bandbreite Kapazität"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Messung der Datenübertragungsrate?', 3, '[{"text": "Netzwerkleistung bewerten", "correct": true, "because": "Effizienz überprüfen"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Software entwickeln", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheiten messen die Datenübertragungsrate?', 5, '[{"text": "Bits pro Sekunde", "correct": true, "because": "Standardmaß"}, {"text": "Bytes pro Sekunde", "correct": true, "because": "Häufig verwendet"}, {"text": "Pixel pro Sekunde", "correct": false, "because": "Bildspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Datenübertragungsrate hängt vom Netzwerk ab. b) Sie ist immer konstant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse der Datenübertragungsrate?', 4, '[{"text": "Netzwerkbelastung", "correct": false, "because": "Beeinflusst Rate"}, {"text": "Übertragungsprotokoll", "correct": false, "because": "Bestimmt Effizienz"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Datenübertragungsrate nur digitale Daten betrifft?', 2, '[{"text": "Ja", "correct": true, "because": "Netzwerkkontext"}, {"text": "Nein", "correct": false, "because": "Primär digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit entspricht 1.000.000 Bits pro Sekunde?', 3, '[{"text": "Megabit/s", "correct": true, "because": "Mbps ist Standard"}, {"text": "Kilobyte/s", "correct": false, "because": "Falsche Umrechnung"}, {"text": "Gigabyte/s", "correct": false, "because": "Zu groß"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Datenübertragungsrate?', 5, '[{"text": "Bandbreite", "correct": true, "because": "Kapazitätsgrenze"}, {"text": "Latenz", "correct": true, "because": "Verzögerung wirkt"}, {"text": "Monitorauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Datenübertragungsrate kann schwanken. b) Sie ist immer maximal. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) abhängig von Bedingungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zur Messung der Datenübertragungsrate?', 4, '[{"text": "Netzwerkverbindung", "correct": false, "because": "Datenfluss nötig"}, {"text": "Messwerkzeug", "correct": false, "because": "Analyse erforderlich"}, {"text": "Küchenzeile", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Datenübertragungsrate unabhängig vom Protokoll?', 2, '[{"text": "Nein", "correct": true, "because": "Protokoll beeinflusst Effizienz"}, {"text": "Ja", "correct": false, "because": "Abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle beeinflussen die Datenübertragungsrate?', 4, '[{"text": "TCP", "correct": true, "because": "Zuverlässigkeit wirkt"}, {"text": "UDP", "correct": true, "because": "Schnelligkeit priorisiert"}, {"text": "HTML", "correct": false, "because": "Kein Übertragungsprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Datenübertragungsrate immer gleich ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Schwankt je nach Bedingungen"}, {"text": "Ja", "correct": false, "because": "Variabel"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Optimierung der Datenübertragungsrate?', 3, '[{"text": "Niedrige Latenz", "correct": true, "because": "Schnelligkeit erhöhen"}, {"text": "Schnelle Hardware", "correct": false, "because": "Sekundär"}, {"text": "Minimale Kosten", "correct": false, "because": "Leistung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Datenübertragungsrate hängt von der Bandbreite ab. b) Sie wird in Watt gemessen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien erhöhen die Datenübertragungsrate?', 5, '[{"text": "Glasfaser", "correct": true, "because": "Hohe Bandbreite"}, {"text": "5G", "correct": true, "because": "Schnelle Mobilfunkrate"}, {"text": "Texteditor", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Messung unwichtig?', 3, '[{"text": "Übertragungsmedium", "correct": false, "because": "Beeinflusst Rate"}, {"text": "Netzwerkbelastung", "correct": false, "because": "Wirkt auf Geschwindigkeit"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann die Datenübertragungsrate durch Störungen sinken?', 3, '[{"text": "Ja", "correct": true, "because": "Interferenzen wirken"}, {"text": "Nein", "correct": false, "because": "Störungen beeinflussen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Datenübertragungsrate nur für Netzwerke gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch interne Übertragung"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Latenz?', 4, '[{"text": "Verzögert Übertragung", "correct": true, "because": "Beeinflusst Rate"}, {"text": "Erhöht Speicher", "correct": false, "because": "Kein Effekt"}, {"text": "Verbessert Grafik", "correct": false, "because": "Irrelevant"}]');
